import{_ as s,o as e,c as i,a2 as n}from"./chunks/framework.CAKCj7G0.js";const k=JSON.parse('{"title":"布局","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/04.HTMLCSS提升/Css3.md","filePath":"DuOneClass/04.HTMLCSS提升/Css3.md"}'),t={name:"DuOneClass/04.HTMLCSS提升/Css3.md"};function l(r,a,p,o,h,d){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="布局" tabindex="-1">布局 <a class="header-anchor" href="#布局" aria-label="Permalink to &quot;布局&quot;">​</a></h1><p><img src="https://s2.loli.net/2025/02/01/FJMq9rs5H37N4Gk.png" alt="image-20210511102549096"></p><p><strong>浮动</strong>：做文字环绕效果</p><p><strong>弹性盒</strong>：单行或单列布局</p><p><strong>网格</strong>：多行多列布局</p><h2 id="弹性盒" tabindex="-1">弹性盒 <a class="header-anchor" href="#弹性盒" aria-label="Permalink to &quot;弹性盒&quot;">​</a></h2><blockquote><p>详细文档见<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/CSS_Flexible_Box_Layout" target="_blank" rel="noreferrer">MDN</a></p><p><a href="https://flexboxfroggy.com/" target="_blank" rel="noreferrer">弹性盒小游戏</a></p></blockquote><h3 id="生成弹性容器和弹性项目" tabindex="-1">生成弹性容器和弹性项目 <a class="header-anchor" href="#生成弹性容器和弹性项目" aria-label="Permalink to &quot;生成弹性容器和弹性项目&quot;">​</a></h3><p><img src="https://s2.loli.net/2025/02/01/G9xXzaJNvFLkUWD.png" alt="image-20210511112624876"></p><p>**默认情况下，**弹性项目沿着主轴依次排列，侧轴拉伸</p><h3 id="更改方向" tabindex="-1">更改方向 <a class="header-anchor" href="#更改方向" aria-label="Permalink to &quot;更改方向&quot;">​</a></h3><p>通过<code>flex-direction</code>可更改主轴方向</p><p><img src="https://s2.loli.net/2025/02/01/oKl4nGwHDhizMTI.png" alt="image-20210511112510632"></p><h3 id="主轴排列" tabindex="-1">主轴排列 <a class="header-anchor" href="#主轴排列" aria-label="Permalink to &quot;主轴排列&quot;">​</a></h3><p>通过<code>justify-content</code>属性，可以影响主轴的排列方式</p><p><img src="https://s2.loli.net/2025/02/01/MIi6F3SwmoZ7grl.png" alt="image-20210511113617325"></p><h3 id="侧轴排列" tabindex="-1">侧轴排列 <a class="header-anchor" href="#侧轴排列" aria-label="Permalink to &quot;侧轴排列&quot;">​</a></h3><p>通过<code>align-items</code>属性，可以影响侧轴的排列方式</p><p><img src="https://s2.loli.net/2025/02/01/WlHvR3YJE1gGNPI.png" alt="image-20210511114016304"></p><h3 id="弹性项目伸缩" tabindex="-1">弹性项目伸缩 <a class="header-anchor" href="#弹性项目伸缩" aria-label="Permalink to &quot;弹性项目伸缩&quot;">​</a></h3><p>所谓伸缩，是指在<strong>主轴方向</strong>上，当<strong>弹性容器</strong>有<strong>额外空间</strong>时，是否需要拉伸，当<strong>空间不足</strong>时，是否需要<strong>压缩</strong></p><p>在<strong>弹性项目</strong>上使用<code>flex</code>属性，可设置拉伸和压缩比例：<code>flex: 拉伸比例 压缩比例 初始尺寸</code></p><p>拉伸示例：</p><p><img src="https://s2.loli.net/2025/02/01/p498B6fu71SXoZs.png" alt="image-20210511120916571"></p><p>压缩示例：</p><p><img src="https://s2.loli.net/2025/02/01/o4OTbYmKyNzXVF8.png" alt="image-20210511121459341"></p><p>默认情况下，<code>flex: 0 1 auto</code></p><h3 id="主轴换行" tabindex="-1">主轴换行 <a class="header-anchor" href="#主轴换行" aria-label="Permalink to &quot;主轴换行&quot;">​</a></h3><p>默认情况，当主轴剩余空间不足时，按照压缩比例进行压缩，但如果设置了主轴换行，则不会压缩，直接换行显示</p><p>给<strong>弹性容器</strong>设置<code>flex-wrap: wrap</code>，即可主轴换行</p><p><img src="https://s2.loli.net/2025/02/01/R8YqLua5K2EpUMl.png" alt="image-20210511123310673"></p><blockquote><p>尽管如此，多行多列仍然推荐使用网格布局</p></blockquote><h2 id="网格" tabindex="-1">网格 <a class="header-anchor" href="#网格" aria-label="Permalink to &quot;网格&quot;">​</a></h2><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/CSS_Grid_Layout" target="_blank" rel="noreferrer">MDN详细文档</a></p><p><a href="http://www.ruanyifeng.com/blog/2019/03/grid-layout-tutorial.html" target="_blank" rel="noreferrer">阮一峰网格布局教程</a></p><p><a href="https://cssgridgarden.com/" target="_blank" rel="noreferrer">网格布局小游戏</a></p></blockquote><p><strong>网格布局是多行多列布局的终极解决方案</strong></p><h3 id="生成网格布局" tabindex="-1">生成网格布局 <a class="header-anchor" href="#生成网格布局" aria-label="Permalink to &quot;生成网格布局&quot;">​</a></h3><p><img src="https://s2.loli.net/2025/02/01/fpriImvjO78Jx1V.png" alt="image-20210511165317363"></p><p>容器生成网格布局后，其所有子元素为<strong>网格项目</strong></p><h3 id="定义行和列" tabindex="-1">定义行和列 <a class="header-anchor" href="#定义行和列" aria-label="Permalink to &quot;定义行和列&quot;">​</a></h3><p><code>grid-template-rows</code>：定义行</p><p><code>grid-template-columns</code>：定义列</p><p><strong>它们的语法是相同的</strong></p><p><img src="https://s2.loli.net/2025/02/01/8NzcEw3Ma26CboA.png" alt="image-20210511172305100"></p><h3 id="改变排列方向" tabindex="-1">改变排列方向 <a class="header-anchor" href="#改变排列方向" aria-label="Permalink to &quot;改变排列方向&quot;">​</a></h3><p>使用属性<code>grid-auto-flow: column</code>，可使子元素按列排放</p><p><img src="https://s2.loli.net/2025/02/01/4p5dm1n6UhMPGic.png" alt="image-20210511173447321"></p><h3 id="单元格之间的间隙" tabindex="-1">单元格之间的间隙 <a class="header-anchor" href="#单元格之间的间隙" aria-label="Permalink to &quot;单元格之间的间隙&quot;">​</a></h3><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">row-gap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 10px; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 行间隙为10px */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">column-gap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 20px; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 列间隙为20px */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gap: 10px 20px; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 行间隙为10px，列间隙为20px */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><img src="https://s2.loli.net/2025/02/01/ypPdc73f6qhzQNg.png" alt="image-20210512132025687"></p><h3 id="单元格内部的对齐" tabindex="-1">单元格内部的对齐 <a class="header-anchor" href="#单元格内部的对齐" aria-label="Permalink to &quot;单元格内部的对齐&quot;">​</a></h3><p>默认情况下，网格项目在单元格内部水平和垂直拉伸，以撑满单元格</p><p>可以使用属性<code>justify-items</code>设置<strong>水平方向</strong>的排列方式</p><p>可以使用属性<code>align-items</code>设置<strong>垂直方向</strong>的排列方式</p><p>它们的可取值是相同的：</p><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">justify-items</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: start 左 | end 右 | </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">center</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 中 | stretch 拉伸;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">align-items</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: start 上 | end 下 | </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">center</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 中 | stretch 拉伸;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><img src="https://s2.loli.net/2025/02/01/pBFl9QSzCr86xGe.png" alt="image-20210511174450356"></p><p>可以使用速写属性<code>place-items: 垂直对齐方式 水平对齐方式</code>同时设置这两个值</p><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">place-items</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: start center; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 垂直靠上，水平居中 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="网格项目定位" tabindex="-1">网格项目定位 <a class="header-anchor" href="#网格项目定位" aria-label="Permalink to &quot;网格项目定位&quot;">​</a></h3><p>默认情况下，网格项目依次排列到单元格中，每个网格占据一个单元格</p><p>但可以对网格项目设置<code>grid-area</code>属性来改变这一行为</p><p>使用方式为：</p><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">grid-area</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 起始行线编号/起始列线编号/结束行线编号/结束列线编号;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="https://s2.loli.net/2025/02/01/kyfcY82GBg5eANw.png" alt="image-20210511180027983"></p><h1 id="视觉" tabindex="-1">视觉 <a class="header-anchor" href="#视觉" aria-label="Permalink to &quot;视觉&quot;">​</a></h1><blockquote><p>所谓视觉类样式，是指不影响盒子位置、尺寸的样式，例如文字颜色、背景颜色、背景图片等</p></blockquote><h2 id="阴影" tabindex="-1">阴影 <a class="header-anchor" href="#阴影" aria-label="Permalink to &quot;阴影&quot;">​</a></h2><h3 id="盒子阴影" tabindex="-1">盒子阴影 <a class="header-anchor" href="#盒子阴影" aria-label="Permalink to &quot;盒子阴影&quot;">​</a></h3><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/box-shadow" target="_blank" rel="noreferrer">MDN详细文档</a></p></blockquote><p>通过<code>box-shadow</code>属性可以设置整个盒子的阴影</p><h3 id="文字阴影" tabindex="-1">文字阴影 <a class="header-anchor" href="#文字阴影" aria-label="Permalink to &quot;文字阴影&quot;">​</a></h3><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/text-shadow" target="_blank" rel="noreferrer">MDN详细文档</a></p></blockquote><p>通过<code>text-shadow</code>可以设置文字阴影</p><h2 id="圆角" tabindex="-1">圆角 <a class="header-anchor" href="#圆角" aria-label="Permalink to &quot;圆角&quot;">​</a></h2><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/border-radius" target="_blank" rel="noreferrer">MDN详细文档</a></p></blockquote><p>通过设置<code>border-radius</code>，可以设置盒子的圆角</p><p><img src="https://s2.loli.net/2025/02/01/Gu2IB57lVvRa9g8.png" alt="image-20210512131026084"></p><p><code>border-radius</code>可以有很多灵活的用法，将下面的代码依次粘贴到页面中测试一下</p><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">border-radius</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 10px; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 同时设置4个角的圆角，半径为10px */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">border-radius</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 50%; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 同时设置4个角的圆角，圆的横向半径为宽度一半，纵向半径为高度一半 */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">border-radius</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 10px 20px 30px 40px; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 分别设置左上、右上、右下、左下的圆角 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="背景渐变" tabindex="-1">背景渐变 <a class="header-anchor" href="#背景渐变" aria-label="Permalink to &quot;背景渐变&quot;">​</a></h2><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/linear-gradient()" target="_blank" rel="noreferrer">MDN详细文档</a></p></blockquote><p>在设置<strong>背景图片</strong>时，除了可以使用<code>url()</code>加载一张背景图，还可以使用<code>linear-gradient()</code>函数设置背景渐变</p><p><code>linear-gradient()</code>用于创建一张渐变的图片，语法为：</p><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 设置渐变背景，方向：从上到下，颜色：从#e66465渐变到#9198e5 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">background: linear-gradient(to bottom, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">#e66465</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">#9198e5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><img src="https://s2.loli.net/2025/02/01/ufit157cyWpXOlm.png" alt="image-20210512135024676"></p><h2 id="变形" tabindex="-1">变形 <a class="header-anchor" href="#变形" aria-label="Permalink to &quot;变形&quot;">​</a></h2><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/transform" target="_blank" rel="noreferrer">MDN详细文档</a></p></blockquote><p>通过<code>transform</code>属性，可以使盒子的形态发生变化</p><p>该属性支持多种变形方案，常见的有:</p><ul><li>translate，平移</li><li>scale，缩放</li><li>rotate，旋转</li></ul><p><strong>无论是哪一种transform，都只是视觉效果的变化，不会影响盒子的布局</strong></p><p><strong>transform不会导致浏览器reflow和rerender，因此效率极高</strong></p><h3 id="translate-平移" tabindex="-1">translate 平移 <a class="header-anchor" href="#translate-平移" aria-label="Permalink to &quot;translate 平移&quot;">​</a></h3><p>使用<code>translate</code>可以让盒子在原来位置上产生位移，类似于相对定位</p><p><img src="https://s2.loli.net/2025/02/01/cCfKJtDg1HyNmWn.png" alt="image-20210512140622630"></p><h3 id="scale-缩放" tabindex="-1">scale 缩放 <a class="header-anchor" href="#scale-缩放" aria-label="Permalink to &quot;scale 缩放&quot;">​</a></h3><p>使用<code>translate</code>可以让盒子在基于原来的尺寸发生缩放</p><p><img src="https://s2.loli.net/2025/02/01/b9ow3K5zkVJ68mG.png" alt="image-20210512141500499"></p><h3 id="rotate-旋转" tabindex="-1">rotate 旋转 <a class="header-anchor" href="#rotate-旋转" aria-label="Permalink to &quot;rotate 旋转&quot;">​</a></h3><p>使用<code>rotate</code>属性可以在原图基础上进行旋转</p><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 在原图的基础上，顺时针旋转45度角 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transform: rotate(45deg); </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 在原图的基础上，顺时针旋转半圈 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transform: rotate(0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.5turn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="改变变形原点" tabindex="-1">改变变形原点 <a class="header-anchor" href="#改变变形原点" aria-label="Permalink to &quot;改变变形原点&quot;">​</a></h3><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/transform-origin" target="_blank" rel="noreferrer">MDN详细文档</a></p></blockquote><p>变形原点的位置，会影响到具体的变形行为</p><p>默认情况下，变形的原点在盒子中心，你可以通过<code>transform-origin</code>来改变它</p><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">transform-origin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: center; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 设置原点在盒子中心 */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">transform-origin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: left top; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 设置原点在盒子左上角 */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">transform-origin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: right bottom; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 设置原点在盒子右下角 */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">transform-origin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 30px 60px; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 设置原点在盒子坐标 (30, 60) 位置 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>试一试，先点击设置原点的按钮来设置原点(已在图片中使用红色小点标记)，然后点击变形按钮进行变形</p><h3 id="多种变形叠加" tabindex="-1">多种变形叠加 <a class="header-anchor" href="#多种变形叠加" aria-label="Permalink to &quot;多种变形叠加&quot;">​</a></h3><p>可以一次性设置多种变形效果</p><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 先旋转45度，再平移(100,100) */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transform: rotate(45deg) translate(100px, 100px);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 先平移(100, 100)，再旋转45度 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transform: translate(100px, 100px) rotate(45deg);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>注意：旋转会导致坐标系也跟着旋转，从而可能影响到后续的变形效果</p><p>下面的例子可以很好的说明这一点</p><p><a href="http://mdrs.yuanjin.tech/html/css-manual/multi-transform.html" target="_blank" rel="noreferrer">http://mdrs.yuanjin.tech/html/css-manual/multi-transform.html</a></p><blockquote><p>本来打算把这个效果嵌入到markdown，但由于嵌入后出现一些未知的bug，因此只能粘贴效果地址了</p></blockquote><h1 id="过渡和动画" tabindex="-1">过渡和动画 <a class="header-anchor" href="#过渡和动画" aria-label="Permalink to &quot;过渡和动画&quot;">​</a></h1><p>使用过渡和动画，可以让css属性变化更加丝滑</p><p><strong>过渡和动画无法对所有的CSS属性产生影响，能够产生影响的只有数值类属性</strong>，例如：颜色、宽高、字体大小等等</p><h2 id="过渡" tabindex="-1">过渡 <a class="header-anchor" href="#过渡" aria-label="Permalink to &quot;过渡&quot;">​</a></h2><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/transition" target="_blank" rel="noreferrer">MDN详细文档</a></p></blockquote><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transition: 过渡属性 持续时间 过渡函数 过渡延迟</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><p><strong>过渡属性</strong></p><p>针对哪个css属性应用过渡。例如填写<code>transform</code>，则表示仅针对<strong>transform</strong>属性应用过渡。</p><p>若填写<code>all</code>或不填写，则表示针对所有css属性都应用过渡</p></li><li><p><strong>持续时间</strong></p><p>css属性变化所持续的时间，需要带上单位。例如<code>3s</code>表示3秒，<code>0.5s</code>或<code>500ms</code>均表示500毫秒</p></li><li><p><strong>过渡函数</strong></p><p>本质是css属性变化的贝塞尔曲线函数，通常直接使用预设值：</p><p><code>ease-in-out</code>：平滑开始，平滑结束</p><p><code>linear</code>：线性变化</p><p><code>ease-in</code>：仅平滑开始</p><p><code>ease-out</code>：仅平滑结束</p></li><li><p><strong>过渡延迟</strong></p><p>书写规则和持续时间一样，表示过渡效果延迟多久后触发，不填则无延迟</p></li></ul><p><strong>在JS中，可以监听元素的<code>transitionstart</code>和<code>transitionend</code>事件，从而在过渡开始和过渡结束时做一些别的事情</strong></p><h2 id="动画" tabindex="-1">动画 <a class="header-anchor" href="#动画" aria-label="Permalink to &quot;动画&quot;">​</a></h2><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/CSS_Animations" target="_blank" rel="noreferrer">MDN详细文档</a></p></blockquote><p><strong>动画的本质是预先定义的一套css变化规则，然后给该规则取个名字</strong></p><p><img src="https://s2.loli.net/2025/02/01/VCsI5e4XQAYtwv6.png" alt="image-20210513172902413"></p><p>然后，其他元素即可使用这样的规则：</p><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">animation: 规则名 持续时间;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在应用规则时，还可以指定更多的信息</p><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">animation: 规则名 持续时间 重复次数 时间函数 动画方向 延迟时间</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>一些细节：</p><ul><li>定义规则时，<code>0%</code>可以书写为<code>from</code></li><li>定义规则时，<code>100%</code>可以书写为<code>to</code></li><li>重复次数为<code>infinite</code>时，表示无限重复</li><li>动画方向为<code>alternate</code>时，表示交替反向，第1次正向，第2次反向，第3次正向，第4次方向，以此类推</li></ul><p><strong>在JS中，可以监听元素的<code>animationstart</code>和<code>animationnend</code>事件，从而在过渡开始和过渡结束时做一些别的事情</strong></p><h1 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h1><h2 id="box-sizing" tabindex="-1">box-sizing <a class="header-anchor" href="#box-sizing" aria-label="Permalink to &quot;box-sizing&quot;">​</a></h2><p>一图胜千言</p><p><img src="https://s2.loli.net/2025/02/01/72wVnKSj8NJ5fc1.png" alt="image-20210514150015660"></p><p>使用<code>border-box</code>控制尺寸更加直观，因此，很多网站都会加入下面的代码</p><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  margin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  padding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  box-sizing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">border-box</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="字体图标" tabindex="-1">字体图标 <a class="header-anchor" href="#字体图标" aria-label="Permalink to &quot;字体图标&quot;">​</a></h2><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/@font-face" target="_blank" rel="noreferrer">MDN font-face 指令</a></p></blockquote><p>css3新增了<code>font-face</code>指令，该指令可以让我们加载网络字体</p><p>其最常见的应用就是字体图标</p><p><strong>字体图标本质上是文字，即通过<code>color</code>设置颜色，通过<code>font-size</code>设置尺寸</strong></p><p>国内使用最多的字体图标平台是<a href="https://www.iconfont.cn/" target="_blank" rel="noreferrer">阿里巴巴矢量图标库</a></p><p>登录平台后即可免费使用其所有字体图标</p><h2 id="图像内容适应" tabindex="-1">图像内容适应 <a class="header-anchor" href="#图像内容适应" aria-label="Permalink to &quot;图像内容适应&quot;">​</a></h2><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/object-fit" target="_blank" rel="noreferrer">MDN详细文档</a></p></blockquote><p>css3属性<code>object-fit</code>可以控制<strong>多媒体内容和与元素</strong>的适应方式，通常应用在<code>img</code>或<code>video</code>元素中</p><p>一图胜千言</p><p>下图中的所有<code>img</code>元素均被固定了宽高，溢出img的部分实际上均不会显示</p><p><img src="https://s2.loli.net/2025/02/01/lIjVT3KCUatdsXM.png" alt="image-20210514134908778"></p><h2 id="视口单位" tabindex="-1">视口单位 <a class="header-anchor" href="#视口单位" aria-label="Permalink to &quot;视口单位&quot;">​</a></h2><p>css3支持使用<code>vw</code>和<code>vh</code>作为单位，分别表示<code>视口宽度</code>和<code>视口高度</code></p><p>例如<code>1vh</code>表示视口高度的<code>1%</code>，<code>100vw</code>表示视口宽度的<code>100%</code></p><h2 id="伪元素选择器" tabindex="-1">伪元素选择器 <a class="header-anchor" href="#伪元素选择器" aria-label="Permalink to &quot;伪元素选择器&quot;">​</a></h2><p>通过<code>::before</code>和<code>::after</code>选择器，可以通过css给元素生成两个子元素</p><p><img src="https://s2.loli.net/2025/02/01/pNFEHTV1YePKJul.png" alt="image-20210514140049244"></p><p>使用伪元素可以避免在HTML中使用过多的空元素</p><p><strong>伪元素必须要有<code>content</code>属性，否则不能生效，如果不需要有元素内容，设置<code>content:&#39;&#39;</code></strong></p><h2 id="平滑滚动" tabindex="-1">平滑滚动 <a class="header-anchor" href="#平滑滚动" aria-label="Permalink to &quot;平滑滚动&quot;">​</a></h2><blockquote><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/scroll-behavior" target="_blank" rel="noreferrer">MDN详细文档</a></p></blockquote><p>使用<code>scroll-behavior: smooth</code>，可以让滚动更加丝滑</p><p>参见MDN效果即可</p>`,164)])])}const g=s(t,[["render",l]]);export{k as __pageData,g as default};
